import{_ as o,l,o as e,c as i,v as r,p as s,x as t,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"网络效应与标准","description":"","frontmatter":{"title":"网络效应与标准","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/network-standards-io.md","filePath":"econ/network-standards-io.md","lastUpdated":1789023840000}'),h={name:"econ/network-standards-io.md"};function c(A,a,B,_,m,u){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="网络效应与标准" tabindex="-1">网络效应与标准 <a class="header-anchor" href="#网络效应与标准" aria-label="Permalink to &quot;网络效应与标准&quot;">​</a></h1><div class="epigraph"><p>兼容把两家的安装基础加总成一张网；不兼容则把采用变成标准之战。胜出的不必是技术更优的，而是预期先协调到的。</p><footer>—— Katz and Shapiro, AER 1985；Farrell and Saloner 标准化与安装基础；David 对 QWERTY 的路径依赖讨论；对照 Tirole 网络章</footer></div><p><a href="/econ/vertical-restraints">上一课</a>用合同内部化垂直链上的外部性。本课缺口是横向的采用外部性：别人用同一系统，我的支付意愿上升。微观<a href="/econ/network-externalities">网络外部性</a>已经写下实现预期与多均衡。产业组织续课要补的是<strong>标准与兼容作为策略</strong>：厂商何时开放接口、何时为不兼容而战，以及这如何改变进入的沉没与定价。后课把同一逻辑接到平台两边。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实现预期下，同一价格可以撑住小网与大网两个不动点。兼容决策把有效网络从「自家用户」改成「可互通用户之和」，需求曲线外移，但独占加价的能力下降。缺口不是再定义 \\(n^e\\)，而是：<strong>兼容是公共品还是封锁工具，标准战锁定的是协调还是质量。</strong> Farrell–Saloner：在位的安装基础可以阻止更优的新技术（过度惯性），也可以因预期跳到新网而抛弃仍有价值的旧网（过度动量）。</p><p>标准可以由协会、主导厂商或政府指定。指定解决协调，也可能把错误技术锁死。本课对照机制，不写标准化学术委员会的程序法。</p><h3 id="标准战不是最好技术胜出" tabindex="-1">标准战不是最好技术胜出 <a class="header-anchor" href="#标准战不是最好技术胜出" aria-label="Permalink to &quot;标准战不是最好技术胜出&quot;">​</a></h3><p>把市场结果读成「revealed quality」，会把协调失败叫成效率。键盘布局、录像带格式是教学对照：即使经验争议仍在，理论要点不变——支付意愿含 \\(n^e\\)，早期份额通过预期放大。质量 \\(s\\) 更高但 \\(n^e\\) 更低的系统可以输。上一课纵向约束保护的是服务；本课保护或开放的是接口。</p><p><span class="marginnote">Katz–Shapiro 的兼容是内生策略：混合兼容使有效网络介于完全互通与完全分裂之间。厂商对弱者开放、对强者封闭，可以是均衡，不必诉诸阴谋叙事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件套。(1) 需求：\\(v(p,n^e)\\)，不动点 \\(n=n^e\\)。(2) 兼容：两家的 \\(n\\) 是否加总；开放可能收费（接口许可）。(3) 标准：事前协调到单一 \\(n\\)，或让市场裂成多标准。进入：不兼容迫使新厂商自建安装基础，沉没上升——接<a href="/econ/entry-exit-sunk">进入与沉没</a>。定价：大网的勒纳用的是含网络的有效弹性，不是把 \\(n\\) 再叫成质量档。</p>',11)),(e(),s(p,null,{default:t(()=>[E(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20VR%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%9E%82%E7%9B%B4%E5%90%88%E5%90%8C%22%5D%20--%3E%20NET%5B%22%E9%87%87%E7%94%A8%E5%A4%96%E9%83%A8%E6%80%A7%20n%5Ee%22%5D%0A%20%20NET%20--%3E%20COMP%5B%22%E5%85%BC%E5%AE%B9%3A%20%E7%BD%91%E7%BB%9C%E5%8A%A0%E6%80%BB%22%5D%0A%20%20NET%20--%3E%20WAR%5B%22%E4%B8%8D%E5%85%BC%E5%AE%B9%3A%20%E6%A0%87%E5%87%86%E4%B9%8B%E6%88%98%22%5D%0A%20%20COMP%20--%3E%20LOCK%5B%22%E9%94%81%E5%85%A5%E6%88%96%E5%8D%8F%E8%B0%83%22%5D%0A%20%20WAR%20--%3E%20LOCK%0A%20%20LOCK%20--%3E%20PLAT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E4%B8%A4%E8%BE%B9%E4%BA%A4%E5%8F%89%E7%BD%91%E7%BB%9C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要用单边勒纳直接读「免费增值」软件：价格结构可能在补贴采用，那是下一课对象。开放接口的许可费把兼容从「免费公共品」改成可定价的接入；费率过高等于事实不兼容。标准必要专利的诉讼是这条许可费的法律外观，本课不写专利法，只留：接入价格改变有效 \\(n\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>策略互补：你采用提高我采用的收益，预期是状态变量。兼容把互补从「同一品牌」扩到「同一标准」，削弱品牌级网络势力、增强标准级势力。在位拒绝兼容，等于把沉没强加给进入者——纵向排他绑的是渠道，这里绑的是用户基础。路径依赖：早期随机或策略性的份额，通过 \\(n^e\\) 变成后期的需求优势，边际质量改进不必翻转结果。</p><p>与差异化定价对照：那里交叉弹性来自偏好异质；这里交叉来自规模进入效用。两套矩阵可以同时存在（不同软件既差异化又联网）。合并模拟若忽略网络，会低估「把两张网合成一张」的涨价或效率。过度惯性与过度动量哪一种更常见，取决于转换成本与预期协调装置，不是取决于哪家的广告预算更大。</p><p><span class="marginnote">Farrell and Saloner 把转换写成带安装基础的动态博弈。本课要的是惯性与动量两种失败，不把全部微分对策写完。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写 Katz–Shapiro 的古诺代数，主干已经有网络外部性课。不把标准写成专利法教程，不进限价簿上的撮合。政府强制标准的政治经济只点到「协调装置」，不展开。下一课：交叉网络——一边的 \\(n\\) 进入另一边的需求，价格结构比总价更要紧。</p><p>后课默认：兼容与标准是策略变量，会改进入 \\(F\\) 与有效弹性。看见锁入，先问预期协调，再问质量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>兼容加总安装基础，不兼容把采用变成标准之战。</li><li>多均衡下，胜出不必是技术更优。</li><li>拒绝兼容可以提高对手的沉没，类似封锁。</li><li>网络加价不能用单边无 \\(n\\) 的勒纳直接读。</li><li>出处：Katz and Shapiro, <em>AER</em> 1985；Farrell and Saloner；David；Tirole。</li></ul>',10))])}const S=o(h,[["render",c]]);export{T as __pageData,S as default};
